package com.eventfinder.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; private final long expiry; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.expiration-ms}") long expiry){ this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8)); this.expiry=expiry;} public String generate(String email,String role){ long now=System.currentTimeMillis(); return Jwts.builder().subject(email).claim("role",role).issuedAt(new Date(now)).expiration(new Date(now+expiry)).signWith(key).compact(); } public String email(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} public String role(String token){return (String)Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().get("role");} public boolean valid(String token){try{email(token);return true;}catch(Exception e){return false;}} }